-- Leads organ -- generated by noctusai_lib.domain.leads.sql

SET search_path = monica, public;

CREATE TABLE IF NOT EXISTS monica.leads (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id                 UUID NOT NULL,
    name                   TEXT NOT NULL CHECK (length(btrim(name)) > 0),
    phone                  TEXT,
    email                  TEXT,
    origin                 TEXT NOT NULL,
    stage                  TEXT NOT NULL,
    position               NUMERIC NOT NULL DEFAULT 0,
    stage_changed_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    notes                  TEXT,
    tags                   TEXT[] NOT NULL DEFAULT '{}',
    whatsapp_connection_id UUID,
    whatsapp_chat_id       TEXT,
    first_contact_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_message_at        TIMESTAMPTZ,
    last_message_preview   TEXT,
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by             UUID
);
-- One lead per WhatsApp chat: the guard that makes `upsert_from_whatsapp` idempotent under concurrent webhooks.
CREATE UNIQUE INDEX IF NOT EXISTS uq_leads_chat
    ON monica.leads (org_id, whatsapp_connection_id, whatsapp_chat_id)
    WHERE whatsapp_connection_id IS NOT NULL AND whatsapp_chat_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_leads_board ON monica.leads (org_id, stage, position);
CREATE INDEX IF NOT EXISTS idx_leads_first_contact ON monica.leads (org_id, first_contact_at DESC, id DESC);
ALTER TABLE monica.leads ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "leads_select_own_org" ON monica.leads;
CREATE POLICY "leads_select_own_org" ON monica.leads FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.leads;
CREATE POLICY "service_role_bypass" ON monica.leads FOR ALL TO service_role USING (true) WITH CHECK (true);
GRANT SELECT ON monica.leads TO authenticated;
GRANT ALL ON monica.leads TO service_role;
